SourceCode.Declaration:
/// <summary>
/// Password hashing and verification for handheld logins.
///
/// PBKDF2 with a per-user random salt. The point of a deliberately slow derivation is that if
/// this table is ever read - a database copy taken for a test refresh, a support export, a backup
/// on a share - the hashes cannot be turned back into passwords at any useful rate. A plain SHA of
/// a password is recovered from a wordlist in seconds; this is not.
///
/// Three properties this file exists to guarantee:
///
/// 1. **The password is never stored, and never logged.** Only the derived hash and its salt.
/// 2. **Every user gets a distinct salt**, so two workers who choose the same password do not get
///    the same hash, and one cracked hash does not reveal the other.
/// 3. **Verification is constant-time.** Comparing hashes with an early-exit comparison leaks how
///    many leading bytes matched, which is enough to recover a hash byte by byte given patience.
///
/// The iteration count is stored per user rather than assumed. It can then be raised for new
/// passwords without invalidating existing ones, which is the only way this stays adjustable as
/// hardware gets faster.
/// </summary>
class HSMobileOpsPassword
{
    private const int SaltLength = 16;
    private const int HashLength = 32;
    private const int MinLength  = 3;
    private const int MaxLength  = 128;

}

Method.Source:
/// <summary>
/// A fresh cryptographically random salt, base64 encoded.
///
/// From the crypto RNG, not Random: a predictable salt defeats the point of having one, since
/// an attacker who can guess salts can precompute against them.
/// </summary>
public static str newSalt()
{
    System.Byte[]                                       saltBytes;
    System.Security.Cryptography.RNGCryptoServiceProvider rng;

    saltBytes = new System.Byte[SaltLength]();
    rng       = new System.Security.Cryptography.RNGCryptoServiceProvider();
    rng.GetBytes(saltBytes);

    return System.Convert::ToBase64String(saltBytes);
}

/// <summary>
/// Derives the stored hash for a password, with the given salt and iteration count.
///
/// The same function serves both setting and checking a password - there is deliberately no
/// separate verification path that could drift from this one and start accepting something
/// this would reject.
/// </summary>
public static str hash(str _password, str _salt, int _iterations)
{
    System.Byte[] saltBytes;
    System.Byte[] hashBytes;
    System.Security.Cryptography.Rfc2898DeriveBytes derive;

    if (!_password || !_salt || _iterations <= 0)
    {
        return '';
    }

    saltBytes = System.Convert::FromBase64String(_salt);
    derive    = new System.Security.Cryptography.Rfc2898DeriveBytes(
        _password, saltBytes, _iterations);
    hashBytes = derive.GetBytes(HashLength);

    return System.Convert::ToBase64String(hashBytes);
}

/// <summary>
/// Whether a password matches a stored hash.
///
/// The comparison never returns early. A normal string comparison stops at the first mismatch,
/// and how long it took reveals how many leading characters were right - which turns guessing
/// a hash from infeasible into a few thousand attempts per character. This one always walks
/// the whole string.
/// </summary>
public static boolean verify(str _password, str _storedHash, str _salt, int _iterations)
{
    str     candidate;
    int     difference;
    int     i;
    int     length;

    if (!_storedHash || !_salt)
    {
        return false;
    }

    candidate = HSMobileOpsPassword::hash(_password, _salt, _iterations);

    // Length is not secret - it is fixed by the algorithm - so an early exit here leaks
    // nothing, and it keeps the loop below from reading past the end of either string.
    if (strLen(candidate) != strLen(_storedHash))
    {
        return false;
    }

    length = strLen(_storedHash);
    for (i = 1; i <= length; i++)
    {
        // Counted, never returned early. The loop always runs the full length, so a hash
        // differing in its first character takes the same time as one differing in its last.
        if (subStr(candidate, i, 1) != subStr(_storedHash, i, 1))
        {
            difference++;
        }
    }

    return difference == 0;
}

/// <summary>
/// Iterations for newly set passwords.
///
/// Stored on the user record rather than read from here at verification time, so raising this
/// strengthens new and changed passwords without locking out everyone whose password was set
/// under the old value. Raise it when the sign-in cost stops being noticeable.
/// </summary>
public static int defaultIterations()
{
    return 120000;
}

/// <summary>
/// Why a password is unacceptable, or an empty string when it is fine.
///
/// Digits only (the handheld types it on a number pad), at least 3. Beyond that, composition rules - an uppercase, a digit, a symbol - reliably produce one
/// predictable password per rule set and a note taped to the handheld cradle, which is worse
/// than a longer passphrase nobody needs to write down.
/// </summary>
public static str policyFailure(str _password)
{
    if (strLen(_password) < MinLength)
    {
        return strFmt('The PIN must be at least %1 characters', MinLength);
    }

    if (strLen(_password) > MaxLength)
    {
        return strFmt('The PIN must be at most %1 characters', MaxLength);
    }

    // The handheld types it on a number pad - a letter could never be entered there.
    if (strKeep(_password, '0123456789') != _password)
    {
        return 'The PIN must be digits only';
    }

    return '';
}
